  margin-bottom: 12px;
  margin-right: 20px;
  font-size: var(--phw-g-regular-text-font-size);
  line-height: 24px;
}

.job-tag-area.style-1 .job-tag:last-child {
  margin-right: 0;
}

.job-tag-area.style-1 .job-tag {
  padding: 0;
