.form-group.active label .float-label {
  font-size: 12px;
  color: var(--brand-color-primary);
}

label.input-check-group {
  position: relative;
  font-weight: normal;
  margin-top: 10px;
  cursor: pointer;
}

label.input-check-group input {
  opacity: 0;
  filter: alpha(opacity=0);
  height: inherit;
  left: 0;
  top: 0;
  position: absolute;
  width: inherit;
}

label.input-check-group .checkbox,
label.input-check-group .radio {
  margin: 0 10px 0 0;
  padding: 0;
  background: var(--widget-bg-white-color) none repeat scroll 0 0;
  -webkit-border-radius: 3px;
  -moz-border-radius: 3px;
  -ms-border-radius: 3px;
  border-radius: 3px;
  border: 1px solid var(--stroke-dark);
  display: inline-block;
  vertical-align: middle;
  height: 16px;
  margin-right: 10px;
  width: 16px;
}

label.input-check-group .checkbox:focus,
label.input-check-group .radio:focus {
  border: 1px solid var(--brand-color-primary);
}

label.input-check-group .checkbox::before,
label.input-check-group .radio::before {
  content: "";
  border-color: var(--brand-color-primary);
  border-image: none;
  border-style: solid;
  border-width: 0 0 2px 2px;
  height: 5px;
  left: 3px;
  position: absolute;
  top: 3px;
  transform: rotate(-45deg);
  -webkit-transform: rotate(-45deg) !important;
  -ms-transform: rotate(-45deg) !important;
  -o-transform: rotate(-45deg) !important;
  width: 8px;
}

label.input-check-group .radio {
  -webkit-border-radius: 50%;
  -moz-border-radius: 50%;
  -ms-border-radius: 50%;
  border-radius: 50%;
  height: 16px;
  width: 16px;
}

label.input-check-group .radio::before {
  border-width: 5px;
  height: 9px;
  left: 2px;
  position: absolute;
  transform: rotate(0deg);
  top: 2px;
  -webkit-border-radius: 50%;
  -moz-border-radius: 50%;
  -ms-border-radius: 50%;
  border-radius: 50%;
}

label.input-check-group input:not(:checked)+.checkbox::before,
label.input-check-group input:not(:checked)+.radio::before {
  opacity: 0;
  filter: alpha(opacity=0);
  transform: scale(0);
  -o-transition: all .2s;
  -moz-transition: all .2s;
  -ms-transition: all .2s;
  -webkit-transition: all .2s;
  transition: all .2s;
}

label.input-check-group input:checked+.checkbox::before,
label.input-check-group input:checked+.radio::before {
  opacity: 1;
  filter: alpha(opacity=100);
  transform: scale(1);
  -o-transition: all .2s;
  -moz-transition: all .2s;
  -ms-transition: all .2s;
  -webkit-transition: all .2s;
  transition: all .2s;
}

.progress {
  background-color: #cecfd1;
